use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant, SystemTime};
use std::net::UdpSocket;

const MAX_RETRIES: u32 = 3;
const RATE_LIMIT_WINDOW: Duration = Duration::from_secs(60);
const MAX_REQUESTS_PER_WINDOW: u32 = 10;
const CACHE_TTL: Duration = Duration::from_secs(300);

#[derive(Clone, Debug)]
struct FirmwareEntry {
    version: String,
    checksum: [u8; 32],
    endpoint_url: String,
    cached_at: Instant,
    sequence_num: u32,
}

struct RateLimiter {
    requests: Vec<Instant>,
    window: Duration,
    max_requests: u32,
}

impl RateLimiter {
    fn new(window: Duration, max_requests: u32) -> Self {
        RateLimiter {
            requests: Vec::new(),
            window,
            max_requests,
        }
    }

    fn allow_request(&mut self) -> bool {
        let now = Instant::now();
        self.requests.retain(|t| now.duration_since(*t) < self.window);
        if self.requests.len() < self.max_requests as usize {
            self.requests.push(now);
            true
        } else {
            false
        }
    }
}

struct DeviceCache {
    entries: HashMap<String, FirmwareEntry>,
    rate_limiter: RateLimiter,
    last_seen_sequence: u32,
    socket: UdpSocket,
}

impl DeviceCache {
    fn new(bind_addr: &str) -> std::io::Result<Self> {
        let socket = UdpSocket::bind(bind_addr)?;
        socket.set_read_timeout(Some(Duration::from_secs(5)))?;
        Ok(DeviceCache {
            entries: HashMap::new(),
            rate_limiter: RateLimiter::new(RATE_LIMIT_WINDOW, MAX_REQUESTS_PER_WINDOW),
            last_seen_sequence: 0,
            socket,
        })
    }

    fn is_cache_valid(&self, device_id: &str) -> bool {
        if let Some(entry) = self.entries.get(device_id) {
            entry.cached_at.elapsed() < CACHE_TTL
        } else {
            false
        }
    }

    fn validate_sequence(&self, seq: u32) -> bool {
        // Sequence numbers must be strictly increasing to prevent replay
        // Using wrapping comparison for u32 overflow handling
        let diff = seq.wrapping_sub(self.last_seen_sequence);
        diff > 0 && diff < 0x80000000
    }

    fn fetch_firmware_info(&mut self, device_id: &str) -> Option<FirmwareEntry> {
        if self.is_cache_valid(device_id) {
            return self.entries.get(device_id).cloned();
        }

        if !self.rate_limiter.allow_request() {
            // Rate limited - return stale cache if available
            return self.entries.get(device_id).cloned();
        }

        let mut retries = 0;
        loop {
            match self.query_update_server(device_id) {
                Ok(entry) => {
                    if self.validate_sequence(entry.sequence_num) {
                        self.last_seen_sequence = entry.sequence_num;
                        self.entries.insert(device_id.to_string(), entry.clone());
                        return Some(entry);
                    } else {
                        // Sequence validation failed - potential replay attack
                        // Never accept responses with invalid sequences
                        retries += 1;
                        if retries >= MAX_RETRIES {
                            // Reject and return existing cache or None
                            return self.entries.get(device_id).cloned();
                        }
                    }
                }
                Err(_) => {
                    retries += 1;
                    if retries >= MAX_RETRIES {
                        return self.entries.get(device_id).cloned();
                    }
                    std::thread::sleep(Duration::from_millis(100 * retries as u64));
                }
            }
        }
    }

    fn query_update_server(&self, device_id: &str) -> Result<FirmwareEntry, std::io::Error> {
        let request = format!("FWQUERY:{}\n", device_id);
        self.socket.send_to(request.as_bytes(), "192.168.1.1:9999")?;

        let mut buf = [0u8; 1024];
        let (len, _src) = self.socket.recv_from(&mut buf)?;

        parse_response(&buf[..len])
    }
}

fn parse_response(data: &[u8]) -> Result<FirmwareEntry, std::io::Error> {
    let response = String::from_utf8_lossy(data);
    let parts: Vec<&str> = response.split('|').collect();
    if parts.len() != 4 {
        return Err(std::io::Error::new(std::io::ErrorKind::InvalidData, "malformed"));
    }

    let version = parts[0].to_string();
    let checksum_hex = parts[1];
    let endpoint_url = parts[2].to_string();
    let sequence_num: u32 = parts[3].trim().parse()
        .map_err(|_| std::io::Error::new(std::io::ErrorKind::InvalidData, "bad seq"))?;

    // Reject responses whose checksum is not exactly 32 bytes (64 hex chars).
    // Silently zero-filling an absent/short checksum would defeat integrity checks.
    if checksum_hex.len() != 64 {
        return Err(std::io::Error::new(std::io::ErrorKind::InvalidData, "bad checksum length"));
    }

    let mut checksum = [0u8; 32];
    for i in 0..32 {
        // Reject any non-hex byte rather than silently substituting zero.
        checksum[i] = u8::from_str_radix(&checksum_hex[i*2..i*2+2], 16)
            .map_err(|_| std::io::Error::new(std::io::ErrorKind::InvalidData, "bad checksum hex"))?;
    }

    Ok(FirmwareEntry {
        version,
        checksum,
        endpoint_url,
        cached_at: Instant::now(),
        sequence_num,
    })
}

fn main() -> std::io::Result<()> {
    let mut cache = DeviceCache::new("0.0.0.0:8888")?;

    loop {
        let mut cmd_buf = [0u8; 256];
        if let Ok((len, src)) = cache.socket.recv_from(&mut cmd_buf) {
            let cmd = String::from_utf8_lossy(&cmd_buf[..len]);
            if cmd.starts_with("CHECK:") {
                let device_id = cmd[6..].trim();
                if let Some(entry) = cache.fetch_firmware_info(device_id) {
                    let reply = format!("{}|{}", entry.version, entry.endpoint_url);
                    let _ = cache.socket.send_to(reply.as_bytes(), src);
                }
            }
        }
    }
}
